pragma solidity ^0.8.20;
contract LearnerProgress {
    mapping(address => uint256) public completed;
    mapping(address => bool) public hasProgress;
    function complete() external { completed[msg.sender] += 1; hasProgress[msg.sender] = true; }
    function progressOf(address learner) external view returns (uint256) { return completed[learner]; }
    function resetSelf() external { delete completed[msg.sender]; delete hasProgress[msg.sender]; }
}

